const fs = require('fs');
const data = JSON.parse(fs.readFileSync('/data/mock_transcripts.json', 'utf8'));

return data.map(session => {
  const turns = session.transcript;
  const sampled = turns.length > 60
    ? [...turns.slice(0, 40), ...turns.slice(-20)]
    : turns;
  return {
    json: {
      session_id: session.id,
      title: session.title,
      created_at: session.created_at,
      participants: session.participants,
      sampled_transcript: sampled,
      full_transcript: turns
    }
  };
});

const session = $input.item.json;
const transcriptText = session.sampled_transcript
  .map(t => t.speaker + ': ' + t.text)
  .join('\n');

const participantInfo = session.participants
  .map(p => `${p.name} (${p.is_team_member ? 'team member' : 'external client'})`)
  .join(', ');

const allInternal = session.participants.every(p => p.is_team_member === true);

return {
  json: {
    session_id: session.session_id,
    title: session.title,
    created_at: session.created_at,
    participants: session.participants,
    full_transcript: session.full_transcript,
    requestBody: {
      model: 'llama3.2',
      stream: false,
      format: 'json',
      messages: [
        {
          role: 'system',
          content: `You are a meeting classifier for GenX Leadership Academy, an executive coaching firm.

Classify the meeting as EXACTLY ONE of these types:
- "Client Coaching": A session where an executive coach (team member) provides personal development, leadership, or career coaching to a paying client (external, non-team member). There MUST be at least one external client participant.
- "Internal Operations": Internal team meetings, tech syncs, process or operational discussions between employees/team members only.
- "Sales Discovery": Sales or business development calls where services are pitched or sold to a prospect.
- "Other": Any other type of meeting.

CRITICAL RULES:
1. If ALL participants are team members (no external clients), it CANNOT be "Client Coaching" — classify as "Internal Operations".
2. "Client Coaching" requires personal growth / leadership coaching dialogue, NOT technical discussions.
3. Return ONLY valid JSON with these exact keys: "meeting_type", "confidence_score" (0.0-1.0), "summary" (one sentence).

No markdown, no explanation, no code blocks.`
        },
        {
          role: 'user',
          content: `Meeting title: "${session.title}"
Participants: ${participantInfo}
All-internal team meeting: ${allInternal}

Transcript:
${transcriptText}

Classify this meeting. Return JSON only.`
        }
      ]
    }
  }
};

const sessionData = $('Build Classification Payload').item.json;
const llmResponse = $input.item.json;

let classification = { meeting_type: 'Other', confidence_score: 0.0, summary: 'Parse failed' };
try {
  const content = llmResponse.message?.content || llmResponse.response || '';
  const match = content.match(/\{[\s\S]*?\}/);
  if (match) {
    const parsed = JSON.parse(match[0]);
    classification = {
      meeting_type: String(parsed.meeting_type || 'Other').trim(),
      confidence_score: parseFloat(parsed.confidence_score) || 0.0,
      summary: String(parsed.summary || '')
    };
  }
} catch (e) {
  // keep defaults on parse failure
}

return {
  json: {
    session_id: sessionData.session_id,
    title: sessionData.title,
    created_at: sessionData.created_at,
    participants: sessionData.participants,
    full_transcript: sessionData.full_transcript,
    meeting_type: classification.meeting_type,
    confidence_score: classification.confidence_score,
    summary: classification.summary
  }
};

const items = $input.all();
const output = [];

for (const item of items) {
  const session = item.json;
  const participants = session.participants || [];
  const coachParticipant = participants.find(p => p.is_team_member === true);
  const coachSpeaker = coachParticipant?.name || '';
  const turns = session.full_transcript || [];

  const frameworkText = turns.map(t => t.speaker + ': ' + t.text).join('\n\n');
  const frameworkChunks = [];
  let pos = 0;
  while (pos < frameworkText.length) {
    let end = Math.min(pos + 600, frameworkText.length);
    if (end < frameworkText.length) {
      const breakAt = frameworkText.lastIndexOf('\n', end);
      if (breakAt > pos) end = breakAt;
    }
    const chunk = frameworkText.slice(pos, end).trim();
    if (chunk.length >= 50) frameworkChunks.push(chunk);
    pos = end;
    if (pos >= frameworkText.length) break;
  }

  const coachTurns = turns.filter(t => coachSpeaker && t.speaker === coachSpeaker);
  const coachText = coachTurns.map(t => t.text).join('\n\n');
  const voiceChunks = [];
  pos = 0;
  while (pos < coachText.length) {
    let end = Math.min(pos + 600, coachText.length);
    if (end < coachText.length) {
      const sentenceBreak = coachText.lastIndexOf('. ', end);
      if (sentenceBreak > pos) end = sentenceBreak + 1;
    }
    const chunk = coachText.slice(pos, end).trim();
    if (chunk.length >= 50) voiceChunks.push(chunk);
    pos = end;
    if (pos >= coachText.length) break;
  }

  frameworkChunks.forEach((chunk, i) => {
    output.push({ json: {
      session_id: session.session_id,
      stream_type: 'framework',
      content: chunk,
      meta_title: session.title,
      meta_created_at: session.created_at,
      meta_chunk_index: i
    }});
  });
  voiceChunks.forEach((chunk, i) => {
    output.push({ json: {
      session_id: session.session_id,
      stream_type: 'voice_sample',
      content: chunk,
      meta_title: session.title,
      meta_created_at: session.created_at,
      meta_speaker: coachSpeaker,
      meta_chunk_index: i
    }});
  });
}

return output;

const chunkData = $('Dual-Stream Parser').item.json;
const embedResponse = $input.item.json;

const rawEmbedding = embedResponse.embeddings?.[0] || embedResponse.embedding || [];
const embeddingStr = '[' + rawEmbedding.join(',') + ']';

const contentEscaped = chunkData.content.replace(/'/g, "''");
const metaStr = JSON.stringify({
  title: chunkData.meta_title,
  created_at: chunkData.meta_created_at,
  chunk_index: chunkData.meta_chunk_index,
  speaker: chunkData.meta_speaker || null
}).replace(/'/g, "''");

const insertSQL = `INSERT INTO knowledge_vault (session_id, stream_type, content, metadata, embedding) VALUES ('${chunkData.session_id}', '${chunkData.stream_type}', '${contentEscaped}', '${metaStr}'::jsonb, '${embeddingStr}'::vector)`;

return { json: { insertSQL } };

const session = $input.item.json;
const esc = s => (s || '').replace(/'/g, "''");
const transcript = JSON.stringify(session.full_transcript || []).replace(/'/g, "''");

const archiveSQL = `INSERT INTO archived_sessions (session_id, title, meeting_type, confidence_score, summary, raw_transcript) VALUES ('${esc(session.session_id)}', '${esc(session.title)}', '${esc(session.meeting_type)}', ${parseFloat(session.confidence_score)||0}, '${esc(session.summary)}', '${transcript}'::jsonb)`;

return { json: { archiveSQL } };
